body, html {
margin: 0; padding: 0;
width: 100%; height: 100%;
background: #000;
font-family: Arial, sans-serif;
}
.main-content {
position: relative;
z-index: 1;
padding: 40px;
color: white;
}
a.glitch-link {
position: absolute;
top: 20px; left: 20px;
color: #0f0;
font-size: 28px;
cursor: pointer;
text-decoration: underline;
z-index: 10;
}
canvas {
position: fixed;
top: 0; left: 0;
width: 100%; height: 100%;
display: none;
z-index: 9999;
pointer-events: none;
background: transparent;
}
